#!/usr/bin/env python3
"""Turn 35 Wave 81: THE OFFICIAL FRIEND MATCH ARTICLE'S MISSING WARNINGS, THE CHALLENGE
STRUCTURE IN FULL, AND TWO MORE REJECTED SOURCES.

Wave 81's centrepieces:

1. THE OFFICIAL FRIEND MATCH ARTICLE (support.ftgames.com 360019064438) - the corpus already
   carried its character set and its quit-forfeit comment, but not its two operational
   warnings. **The code-collision hazard**: "Try to think of a unique code, as choosing one in
   use could see you joining the wrong match." And the implication the corpus had only as a
   comment: **friend matches DO pay rewards - a quit is what forfeits them.**

2. THE CHALLENGE STRUCTURE IN FULL - the three tracks, where they live, what the objectives
   actually are, and the Season Points lever nobody had written down: win Career matches with
   four or more goals.

3. TWO MORE REJECTED SOURCES. The fandom wiki's Coins page carries impossible figures (a
   stadium bonus of "9999999990 coins"), and lfbb.net publishes a fabricated daily routine.
   Both are now formally rejected.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w81')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="official"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_fm=new_ev("support.ftgames.com 360019064438 'How do I play a Friend Match?' (OFFICIAL - the code rules, the collision warning, the DLL entry point, the stats tracking, and the comment that friend matches pay no reward when the opponent quits), App Store DLS26 version history (the Summer Spotlight changes: more friend match options, Daily Bonus, Scenario update, transfer lock-player upgrades), bluestacks free-rewards guide (the full challenge structure - Daily, Weekly and Career tracks at the bottom left of the home screen, the objective types, the post-match 30-second ad that doubles coins, the Commercial L2/L3 figures, the Global Challenge Cup at 10 gems per round), bluestacks beginner guide (Exhibition as the offline friendly space with a room code and no rewards), gamingonphone DLS26 beginner + DLS25 friend guides (the Exhibition/Friend Match navigation and the six-vs-three Career match inconsistency), gamingonphone DLS26 career guide (Daily Challenges as the most important progression system), kostenlose-spiele-apps.de DLS26 (Exhibition as the training ground - 'no points, no risk, but plenty of learning effect'), r/DreamLeagueSoccer 18dqq9e DLS24 beginner guide (the challenges box, the video-icon reroll, and the 4+ goals tip for Season Points), r/DreamLeagueSoccer 1i75pm4 (the scenario completion rule), r/DreamLeagueSoccer ktwxpz (the practice surfaces), sportsdunia DLS26 clans guide (the clan route to playing a friend), exophase.com DLS26 Android achievements (40 achievements, 20,000 XP, 40,351 obtainable EXP), dream-league-soccer.fandom.com/wiki/Coins (REJECTED - corrupted figures), lfbb.net gems-and-coins guide (REJECTED - fabricated routine), eslamgaming (FLAGGED source)",
    "THE OFFICIAL FRIEND MATCH ARTICLE, THE CHALLENGE STRUCTURE IN FULL, AND TWO REJECTED SOURCES. (1) THE OFFICIAL FRIEND MATCH ARTICLE, which the corpus had mined for its character set and its quit-forfeit comment but not for its two operational warnings. **THE CODE-COLLISION HAZARD**: 'Try to think of a unique code, as choosing one in use could see you joining the wrong match.' So a common code like DLS152 (the example every community guide uses) is the failure mode. **AND THE REWARD POSITION, now explicit**: the article's own comment thread reports 'Friend matches don't give any rewards when your opponent quits the match! So unfair to the winner' - which establishes that friend matches DO pay rewards in the normal case, and that a quit is what forfeits them. Combined with the corpus's CLAIM-164 (Dream Point Boosts do NOT apply to friend matches), the picture is complete: friend matches pay, they are simply not DP-boosted, and an opponent quitting denies the winner the payout. (2) THE ENTRY POINT, official: 'You can find the Friend Match feature by tapping the Dream League Live (Multiplayer) button on the main home screen. Your Friend Match stats will be tracked here too.' Community guides place Friend Match one level deeper - DLL tab, then Exhibition Mode, then Friend Match - so there is a navigation discrepancy between the official article and the community path; the official surface is authoritative. (3) THE CHALLENGE STRUCTURE IN FULL: the Challenges section sits at the **bottom left of the home screen** and is divided into **Daily, Weekly and Career** tracks. Daily objectives are things like 'scoring a header goal or keeping a clean sheet' and take about 30 minutes; each individual daily challenge pays coins and completing the full daily set pays a fixed amount of gems. Weekly works the same way with gems for the full set. **Career Challenges are tied to Academy Division progress** and pay gems per objective, which is what makes regular Career play doubly worthwhile. (4) THE SEASON POINTS LEVER, previously unrecorded: 'To get more points, win career matches with many goals (4+).' So goal count is a Season Points input, not just a coin one - which matters because 400 SP is the Season Pass activation threshold. (5) THE POST-MATCH AD, corroborated in full: a 30-second optional ad at the end of each match that **doubles** the post-match coin earnings, with a second optional ad for Dream Points. (6) SUMMER SPOTLIGHT CHANGES from the official version history: '**More friend match options** - add friends and play games more easily', '**Daily Bonus** - get rewarded for playing regularly', '**Scenario update** - more bonus objectives and rewards in this special mode', and 'Transfer upgrades - manage lock players in more ways than before'. So the Scenario mode's reward structure was expanded in DLS26, and Friend Match was reworked. (7) EXHIBITION is the offline friendly space: no rewards, no risk, and it is the correct surface for the corpus's three device-testable gaps (through balls, the secondary press, the offside trap) because testing there costs nothing. German-language DLS26 guide: 'Keine Punkte, kein Risiko - aber jede Menge Lerneffekt' (no points, no risk, but plenty of learning effect). (8) A NAVIGATION ERRATUM: gamingonphone's DLS25 guide is internally inconsistent on the DLL unlock - it first says 'complete six Career mode matches' and then 'Once you complete the three Career mode matches'. The corpus's six-match figure (C-025, resolved) stands. (9) THE CLAN ROUTE TO A FRIEND MATCH: 'you and your friend must be in the same clan to play matches against each other' - Dream League Live, Clan, select the member. This is a second, separate route from Friend Match, and it is consistent with the corpus's finding that clan-internal matches pay clan points. (10) EXOPHASE corroborates the Android achievement figures exactly - 40 achievements, 20,000 XP - and adds **40,351 obtainable EXP**, a figure the corpus did not have. (11) TWO REJECTED SOURCES. The fandom wiki's Coins page carries impossible numbers ('1000.000 coins per goal', 'a stadium bonus, which is between 9999999990 coins') - it is corrupted and must not be cited for any economy figure. lfbb.net publishes a fabricated daily routine ('600 bonus gems just from finishing in the top 50', 'each win gives 500 coins') that matches no other source; both are formally rejected.",
    "THE OFFICIAL FRIEND MATCH ARTICLE'S MISSING WARNINGS: a code already in use can drop you into the wrong match, so use a unique code rather than the DLS152 example every guide copies. FRIEND MATCHES DO PAY REWARDS - it is the opponent quitting that forfeits them, and Dream Point Boosts never apply to friend matches. THE CHALLENGE STRUCTURE: Daily, Weekly and Career tracks at the bottom left of the home screen; daily objectives are things like a header goal or a clean sheet; each daily challenge pays coins and the full daily set pays gems; Career Challenges are tied to Academy Division progress. THE SEASON POINTS LEVER: win Career matches with 4+ goals to feed the 400-SP Season Pass threshold. SUMMER SPOTLIGHT added more friend match options, a Daily Bonus, and expanded Scenario rewards. EXHIBITION has no rewards and no risk, which makes it the correct surface for the three device-testable gaps. The clan route is a second way to play a friend. EXOPHASE corroborates 40 achievements / 20,000 XP and adds 40,351 obtainable EXP. TWO MORE REJECTED SOURCES: the fandom wiki's Coins page (corrupted figures) and lfbb.net (fabricated routine)",
    "THE OFFICIAL FRIEND MATCH ARTICLE, THE CHALLENGE STRUCTURE, AND TWO REJECTED SOURCES",
    quality="official")

add_claim("THE CODE-COLLISION HAZARD, official: 'Try to think of a unique code, as choosing one in use could see you joining the wrong match.' The code every community guide copies - DLS152 - is precisely the failure case. Use a code only you and your opponent know.", 1, "multiplayer/friend-match-code-collision", [e_fm], notes="Official warning the corpus had not recorded")
add_claim("FRIEND MATCHES DO PAY REWARDS - it is the opponent quitting that forfeits them. The official article's own comment thread reports 'Friend matches don't give any rewards when your opponent quits the match! So unfair to the winner', which establishes the normal case pays and the quit is the exception. Combined with CLAIM-164 (Dream Point Boosts never apply to friend matches): friend matches pay, they are simply not DP-boosted.", 1, "multiplayer/friend-match-rewards-and-quit-forfeit", [e_fm])
add_claim("The official entry point for Friend Match: 'You can find the Friend Match feature by tapping the Dream League Live (Multiplayer) button on the main home screen. Your Friend Match stats will be tracked here too.' Community guides place it one level deeper (DLL tab, then Exhibition Mode, then Friend Match) - **the official surface is authoritative for the entry point.**", 2, "multiplayer/friend-match-official-entry-point", [e_fm], notes="Records a navigation discrepancy between the official article and the community path")
add_claim("THE CHALLENGE STRUCTURE IN FULL: the Challenges section sits at the **bottom left of the home screen** and has three tracks - **Daily, Weekly and Career**. Daily objectives are things like 'scoring a header goal or keeping a clean sheet' and take about 30 minutes; **each individual daily challenge pays coins and completing the full daily set pays a fixed amount of gems**. Weekly works the same way, with gems for the full weekly set.", 2, "economy/challenge-structure-three-tracks", [e_fm])
add_claim("CAREER CHALLENGES ARE TIED TO ACADEMY DIVISION PROGRESS and award gems on each completed objective - which is what makes regular Career play pay twice, in coins and in gems.", 3, "economy/career-challenges-academy-division", [e_fm])
add_claim("THE SEASON POINTS LEVER, previously unrecorded: 'To get more points, win career matches with many goals (4+).' So goal count feeds Season Points as well as coins - which matters directly, because 400 Season Points is the Season Pass activation threshold.", 3, "economy/season-points-four-goals", [e_fm])
add_claim("The post-match ad, corroborated in full: a 30-second optional video at the end of each match that **doubles** the post-match coin earnings, with a second optional ad available to boost Dream Points. Ads appear after every Career match and pay once per match.", 2, "economy/post-match-ad-doubles-coins", [e_fm], notes="Second source for CLAIM-182 and CLAIM-249")
add_claim("SUMMER SPOTLIGHT CHANGES, from the official version history: '**More friend match options** - add friends and play games more easily' · '**Daily Bonus** - get rewarded for playing regularly' · '**Scenario update** - more bonus objectives and rewards in this special mode' · 'Transfer upgrades - manage lock players in more ways than before'. So Friend Match was reworked and the Scenario reward structure was expanded in DLS26.", 1, "patching/summer-spotlight-friend-and-scenario-changes", [e_fm])
add_claim("EXHIBITION is the offline friendly space with a room code, **no rewards and no risk** - 'Keine Punkte, kein Risiko - aber jede Menge Lerneffekt.' That makes it the correct surface for the corpus's three device-testable gaps (through balls, the secondary press, the offside trap): testing there costs nothing and cannot damage a tier, a streak or a leaderboard position.", 3, "modes/exhibition-as-the-test-surface", [e_fm], notes="Operational synthesis: the three open gaps are all testable for free in Exhibition")
add_claim("A SECOND ROUTE TO PLAY A FRIEND, separate from Friend Match: through the clan. 'You and your friend must be in the same clan to play matches against each other' - Dream League Live, then Clan, then select the member. Consistent with the corpus's finding that clan-internal matches pay clan points.", 3, "multiplayer/clan-route-to-friend-match", [e_fm])
add_claim("EXOPHASE corroborates the Android achievement figures exactly - **40 achievements, 20,000 XP** - and adds a figure the corpus did not have: **40,351 obtainable EXP**.", 3, "achievements/exophase-40351-exp", [e_fm])
add_claim("NAVIGATION ERRATUM: gamingonphone's DLS25 friend guide is internally inconsistent on the DLL unlock, saying first 'complete six Career mode matches' and then 'Once you complete the three Career mode matches'. **The corpus's six-match figure stands** (C-025, resolved from the official article); the 'three' is a drafting error in that one guide.", 4, "errata/dll-unlock-six-vs-three", [e_fm])
add_claim("REJECTED SOURCE: dream-league-soccer.fandom.com/wiki/Coins. The page carries impossible economy figures - '1000.000 coins per goal', '10000 00000 coins if you keep a clean sheet', and 'a stadium bonus, which is between 9999999990 coins'. The page is corrupted and must not be cited for any coin figure. **This is the first fandom-wiki rejection in the register.**", 4, "errata/fandom-coins-page-rejected", [e_fm], notes="First fandom-wiki rejection; its Stadium page remains usable for structure only")
add_claim("REJECTED SOURCE: lfbb.net. Its DLS26 gems-and-coins guide publishes a fabricated daily routine - '600 bonus gems just from finishing in the top 50' in week one, and 'each win gives 500 coins' - neither of which matches any other source in the corpus. Treat the whole site as an AI content farm.", 4, "errata/lfbb-net-rejected", [e_fm], notes="Second new rejection this wave")

for p in ['EV-494_official_friend_match.html','EV-494b_challenge_structure.html','EV-494c_summer_spotlight_version_history.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
